def investigate(context, acquire):
    spans = acquire("spans")
    population = acquire("population")

    def union_length(intervals):
        if not intervals:
            return 0.0
        ordered = sorted(intervals)
        total = 0.0
        cur_start = ordered[0][0]
        cur_end = ordered[0][1]
        for start, end in ordered[1:]:
            if start > cur_end:
                total += cur_end - cur_start
                cur_start = start
                cur_end = end
            else:
                if end > cur_end:
                    cur_end = end
        total += cur_end - cur_start
        return total

    def period_requests(period):
        by_rid = {}
        for row in spans:
            if row["period"] != period:
                continue
            rid = row["rid"]
            by_rid.setdefault(rid, []).append((row["t0"], row["t1"]))
        return by_rid

    def period_classes(period):
        classes = {}
        for row in spans:
            if row["period"] == period:
                classes[row["rid"]] = row["cohort"]
        return classes

    def population_counts(period):
        counts = {}
        for row in population:
            if row["period"] == period:
                counts[row["class"]] = counts.get(row["class"], 0) + row["count"]
        return counts

    def observed_counts(period):
        counts = {}
        for rid, cls in period_classes(period).items():
            counts[cls] = counts.get(cls, 0) + 1
        return counts

    def duplicate_delivery(period):
        seen = {}
        for row in spans:
            if row["period"] != period:
                continue
            key = (row["rid"], row["sid"])
            sig = (row["t0"], row["t1"], row["cohort"])
            if key in seen:
                if seen[key] != sig:
                    return "conflict"
                return "duplicate"
            seen[key] = sig
        return None

    def workload_shift():
        before = population_counts("before")
        after = population_counts("after")
        classes = set(before) | set(after)
        total_before = sum(before.values())
        total_after = sum(after.values())
        if total_before == 0 or total_after == 0:
            return False
        for cls in classes:
            if abs(before.get(cls, 0) / total_before - after.get(cls, 0) / total_after) > 1e-8:
                return True
        return False

    findings = []
    unresolved = []

    dup_before = duplicate_delivery("before")
    dup_after = duplicate_delivery("after")
    if dup_before == "conflict" or dup_after == "conflict":
        unresolved.append("conflicting_event")
    elif dup_before == "duplicate" or dup_after == "duplicate":
        findings.append("duplicate_delivery")

    if workload_shift():
        findings.append("workload_shift")

    for period in ("before", "after"):
        obs = observed_counts(period)
        pop = population_counts(period)
        for cls in set(obs) | set(pop):
            if obs.get(cls, 0) != pop.get(cls, 0):
                unresolved.append("incomplete_coverage")
                break

    units = context.get("clock_units", {})
    if units.get("before") != units.get("after"):
        unresolved.append("unknown_clock_unit")

    ratio = None
    if not unresolved:
        before_req = period_requests("before")
        after_req = period_requests("after")
        before_cls = period_classes("before")
        after_cls = period_classes("after")
        before_pop = population_counts("before")
        total_before = sum(before_pop.values())

        before_means = {}
        for rid, intervals in before_req.items():
            cls = before_cls[rid]
            before_means.setdefault(cls, []).append(union_length(intervals))
        after_means = {}
        for rid, intervals in after_req.items():
            cls = after_cls[rid]
            after_means.setdefault(cls, []).append(union_length(intervals))

        std_before = 0.0
        std_after = 0.0
        for cls, count in before_pop.items():
            weight = count / total_before
            bvals = before_means.get(cls, [])
            avals = after_means.get(cls, [])
            if bvals:
                std_before += weight * (sum(bvals) / len(bvals))
            if avals:
                std_after += weight * (sum(avals) / len(avals))

        if std_before != 0:
            ratio = std_after / std_before
            if ratio > 1.2 + 1e-8:
                findings.append("latency_regression")
            elif ratio < 0.8 - 1e-8:
                findings.append("latency_improvement")
            else:
                findings.append("latency_stable")

    return {"findings": findings, "unresolved": unresolved, "ratio": ratio}

