def investigate(context, acquire):
    spans = acquire("spans")
    population = acquire("population")

    def unit_ok(period):
        units = context.get("clock_units", {})
        u = units.get(period)
        return u is not None and u != "unknown"

    def span_key(row):
        return (row["period"], row["rid"], row["sid"])

    def span_sig(row):
        return (row["t0"], row["t1"], row["cohort"])

    seen = {}
    dup = False
    conflict = False
    for row in spans:
        k = span_key(row)
        s = span_sig(row)
        if k in seen:
            if seen[k] == s:
                dup = True
            else:
                conflict = True
        else:
            seen[k] = s

    pop = {}
    for row in population:
        pop[(row["period"], row["class"])] = row["count"]

    classes = set()
    for row in population:
        classes.add(row["class"])
    for row in spans:
        classes.add(row["cohort"])

    before_props = {}
    after_props = {}
    for c in classes:
        b = pop.get(("before", c), 0)
        a = pop.get(("after", c), 0)
        before_props[c] = b
        after_props[c] = a
    tb = sum(before_props.values())
    ta = sum(after_props.values())
    if tb > 0:
        for c in before_props:
            before_props[c] = before_props[c] / tb
    if ta > 0:
        for c in after_props:
            after_props[c] = after_props[c] / ta

    shift = False
    for c in classes:
        if abs(before_props[c] - after_props[c]) > 1e-12:
            shift = True

    def request_quantity(rows, contract):
        by_req = {}
        for row in rows:
            by_req.setdefault(row["rid"], []).append(row)
        out = {}
        for rid, rs in by_req.items():
            if "billed" in contract:
                total = 0.0
                for r in rs:
                    total = total + (r["t1"] - r["t0"])
                out[rid] = total
            elif "elapsed" in contract:
                lo = min(r["t0"] for r in rs)
                hi = max(r["t1"] for r in rs)
                out[rid] = hi - lo
            else:
                ivs = sorted((r["t0"], r["t1"]) for r in rs)
                total = 0.0
                cur0 = None
                cur1 = None
                for iv in ivs:
                    if cur0 is None:
                        cur0 = iv[0]
                        cur1 = iv[1]
                    elif iv[0] <= cur1:
                        if iv[1] > cur1:
                            cur1 = iv[1]
                    else:
                        total = total + (cur1 - cur0)
                        cur0 = iv[0]
                        cur1 = iv[1]
                if cur0 is not None:
                    total = total + (cur1 - cur0)
                out[rid] = total
        return out

    contract = context.get("quantity_contract", "")

    by_period = {"before": [], "after": []}
    for row in spans:
        by_period[row["period"]].append(row)

    q = {}
    for period in ("before", "after"):
        q[period] = request_quantity(by_period[period], contract)

    cohort_of = {}
    for row in spans:
        cohort_of[(row["period"], row["rid"])] = row["cohort"]

    incomplete = False
    for period in ("before", "after"):
        obs = {}
        for rid in q[period]:
            c = cohort_of.get((period, rid))
            obs[c] = obs.get(c, 0) + 1
        for c in classes:
            if obs.get(c, 0) != pop.get((period, c), 0):
                incomplete = True

    unknown = (not unit_ok("before")) or (not unit_ok("after"))

    findings = []
    if dup:
        findings.append("duplicate_delivery")
    if shift:
        findings.append("workload_shift")

    unresolved = []
    if conflict:
        unresolved.append("conflicting_event")
    if incomplete:
        unresolved.append("incomplete_coverage")
    if unknown:
        unresolved.append("unknown_clock_unit")

    if unresolved:
        return {"findings": findings, "unresolved": unresolved, "ratio": None}

    def class_mean(period, c):
        vals = [q[period][rid] for rid in q[period] if cohort_of.get((period, rid)) == c]
        if not vals:
            return 0.0
        return sum(vals) / len(vals)

    sb = 0.0
    sa = 0.0
    for c in classes:
        sb = sb + before_props[c] * class_mean("before", c)
        sa = sa + before_props[c] * class_mean("after", c)

    ratio = sa / sb
    if ratio > 1.2 + 1e-8:
        findings.append("latency_regression")
    elif ratio < 0.8 - 1e-8:
        findings.append("latency_improvement")
    else:
        findings.append("latency_stable")

    return {"findings": findings, "unresolved": unresolved, "ratio": ratio}

