def investigate(context, acquire):
    spans = acquire("spans")
    population = acquire("population")

    def merge_intervals(intervals):
        if not intervals:
            return []
        ordered = sorted(intervals)
        merged = [list(ordered[0])]
        for start, end in ordered[1:]:
            if start <= merged[-1][1]:
                if end > merged[-1][1]:
                    merged[-1][1] = end
            else:
                merged.append([start, end])
        return merged

    def union_length(intervals):
        return sum(end - start for start, end in merge_intervals(intervals))

    def class_of(rid, cohort_map):
        return cohort_map.get(rid)

    periods = ["before", "after"]
    findings = []
    unresolved = []

    # Duplicate delivery: identical operation record appears more than once.
    seen_records = set()
    duplicate = False
    for row in spans:
        key = (row["period"], row["rid"], row["sid"], row["cohort"], row["t0"], row["t1"])
        if key in seen_records:
            duplicate = True
        seen_records.add(key)
    if duplicate:
        findings.append("duplicate_delivery")

    # Conflicting records for same operation ID within a period.
    op_signatures = {}
    conflicting = False
    for row in spans:
        key = (row["period"], row["sid"])
        sig = (row["rid"], row["cohort"], row["t0"], row["t1"])
        if key in op_signatures and op_signatures[key] != sig:
            conflicting = True
        op_signatures[key] = sig
    if conflicting:
        unresolved.append("conflicting_event")

    # Unknown clock unit.
    units = context.get("clock_units", {})
    for period in periods:
        unit = units.get(period)
        if unit is None or str(unit).strip().lower() in ("", "unknown"):
            unresolved.append("unknown_clock_unit")
            break

    # Population proportions and workload shift.
    pop_counts = {}
    for row in population:
        pop_counts[(row["period"], row["class"])] = row["count"]

    before_total = sum(pop_counts.get(("before", c), 0) for c in set(k[1] for k in pop_counts if k[0] == "before"))
    after_total = sum(pop_counts.get(("after", c), 0) for c in set(k[1] for k in pop_counts if k[0] == "after"))

    before_props = {}
    after_props = {}
    for (period, cls), count in pop_counts.items():
        if period == "before" and before_total:
            before_props[cls] = count / before_total
        if period == "after" and after_total:
            after_props[cls] = count / after_total

    all_classes = set(before_props) | set(after_props)
    shift = False
    for cls in all_classes:
        if abs(before_props.get(cls, 0) - after_props.get(cls, 0)) > 1e-8:
            shift = True
    if shift:
        findings.append("workload_shift")

    # Incomplete coverage: observed distinct requests per class vs population counts.
    observed = {}
    for row in spans:
        key = (row["period"], row["cohort"])
        observed.setdefault(key, set()).add(row["rid"])
    incomplete = False
    for (period, cls), rids in observed.items():
        expected = pop_counts.get((period, cls), 0)
        if len(rids) != expected:
            incomplete = True
    for (period, cls), count in pop_counts.items():
        if (period, cls) not in observed and count > 0:
            incomplete = True
    if incomplete:
        unresolved.append("incomplete_coverage")

    # If unresolved, ratio must be null and no latency conclusion.
    if unresolved:
        return {"findings": findings, "unresolved": unresolved, "ratio": None}

    # Compute per-request union length (active time).
    request_intervals = {}
    request_class = {}
    for row in spans:
        key = (row["period"], row["rid"])
        request_intervals.setdefault(key, []).append((row["t0"], row["t1"]))
        request_class[key] = row["cohort"]

    request_means = {}
    for period in periods:
        by_class = {}
        for (p, rid), intervals in request_intervals.items():
            if p != period:
                continue
            cls = request_class[(p, rid)]
            by_class.setdefault(cls, []).append(union_length(intervals))
        request_means[period] = {cls: sum(vals) / len(vals) for cls, vals in by_class.items()}

    # Standardize using BEFORE population proportions for both periods.
    before_mean = 0.0
    after_mean = 0.0
    for cls, prop in before_props.items():
        before_mean += prop * request_means["before"].get(cls, 0.0)
        after_mean += prop * request_means["after"].get(cls, 0.0)

    if before_mean == 0:
        return {"findings": findings, "unresolved": unresolved, "ratio": None}

    ratio = after_mean / before_mean
    if ratio > 1.2 + 1e-8:
        findings.append("latency_regression")
    elif ratio < 0.8 - 1e-8:
        findings.append("latency_improvement")
    else:
        findings.append("latency_stable")

    return {"findings": findings, "unresolved": unresolved, "ratio": ratio}

