            observed = set(row["rid"] for row in spans if row["period"] == period and row["cohort"] == cls)
            expected = pop.get((period, cls), 0)
            if len(observed) != expected:
                if "incomplete_coverage" not in unresolved:
                    unresolved.append("incomplete_coverage")

    before_props = {}
    after_props = {}
    before_total = sum(pop.get(("before", cls), 0) for cls in classes)
    after_total = sum(pop.get(("after", cls), 0) for cls in classes)
    for cls in classes:
        before_props[cls] = pop.get(("before", cls), 0) / before_total if before_total else 0.0
        after_props[cls] = pop.get(("after", cls), 0) / after_total if after_total else 0.0

    if any(abs(before_props[cls] - after_props[cls]) > 1e-12 for cls in classes):
