                requests = by_period_class.get((period, cls), {})
                if requests:
                    quantities = [request_quantity(rows, contract) for rows in requests.values()]
                    class_means[(period, cls)] = sum(quantities) / len(quantities)
                else:
                    class_means[(period, cls)] = 0.0

        before_std = sum(before_props[cls] * class_means[("before", cls)] for cls in classes)
        after_std = sum(before_props[cls] * class_means[("after", cls)] for cls in classes)

        if before_std != 0:
            ratio = after_std / before_std
            if ratio > 1.2 + 1e-8:
                findings.append("latency_regression")
            elif ratio < 0.8 - 1e-8:
                findings.append("latency_improvement")
            else:
                findings.append("latency_stable")

