def investigate(context, acquire):
    spans = acquire("spans")
    population = acquire("population")

    def merge_intervals(intervals):
        if not intervals:
            return 0.0
        ordered = sorted(intervals)
        total = 0.0
        start = ordered[0][0]
        end = ordered[0][1]
        for a, b in ordered[1:]:
            if a > end:
                total += end - start
                start = a
                end = b
            elif b > end:
                end = b
        total += end - start
        return total

    def request_durations(period):
        by_rid = {}
        for row in spans:
            if row["period"] != period:
                continue
            rid = row["rid"]
            by_rid.setdefault(rid, []).append((row["t0"], row["t1"]))
        return {rid: merge_intervals(ivs) for rid, ivs in by_rid.items()}

    def class_of(period):
        result = {}
        for row in spans:
            if row["period"] == period:
                result[row["rid"]] = row["cohort"]
        return result

    def population_counts(period):
        counts = {}
        for row in population:
            if row["period"] == period:
                counts[row["class"]] = counts.get(row["class"], 0) + row["count"]
        return counts

    def observed_counts(period):
        counts = {}
        for rid, cohort in class_of(period).items():
            counts[cohort] = counts.get(cohort, 0) + 1
        return counts

    def duplicate_delivery():
        seen = set()
        for row in spans:
            key = (row["period"], row["sid"], row["t0"], row["t1"])
            if key in seen:
                return True
            seen.add(key)
        return False

    def conflicting_event():
        by_sid = {}
        for row in spans:
            key = (row["period"], row["sid"])
            val = (row["t0"], row["t1"])
            if key in by_sid and by_sid[key] != val:
                return True
            by_sid[key] = val
        return False

    def workload_shift():
        before = population_counts("before")
        after = population_counts("after")
        total_before = sum(before.values())
        total_after = sum(after.values())
        if total_before == 0 or total_after == 0:
            return False
        classes = set(before) | set(after)
        for c in classes:
            pb = before.get(c, 0) / total_before
            pa = after.get(c, 0) / total_after
            if abs(pb - pa) > 1e-8:
                return True
        return False

    def incomplete_coverage():
        for period in ("before", "after"):
            obs = observed_counts(period)
            pop = population_counts(period)
            for c in set(obs) | set(pop):
                if obs.get(c, 0) != pop.get(c, 0):
                    return True
        return False

    def unknown_clock_unit():
        units = context.get("clock_units", {})
        for period in ("before", "after"):
            u = units.get(period)
            if u is None or str(u).strip().lower() in ("", "unknown", "none"):
                return True
        return False

    findings = []
    unresolved = []

    if duplicate_delivery():
        findings.append("duplicate_delivery")
    if workload_shift():
        findings.append("workload_shift")
    if conflicting_event():
        unresolved.append("conflicting_event")
    if incomplete_coverage():
        unresolved.append("incomplete_coverage")
    if unknown_clock_unit():
        unresolved.append("unknown_clock_unit")

    if unresolved:
        return {"findings": findings, "unresolved": unresolved, "ratio": None}

    before_dur = request_durations("before")
    after_dur = request_durations("after")
    before_class = class_of("before")
    after_class = class_of("after")
    before_pop = population_counts("before")
    after_pop = population_counts("after")

    total_before = sum(before_pop.values())
    total_after = sum(after_pop.values())

    def class_mean(durations, classes, pop, total):
        if total == 0:
            return 0.0
        acc = 0.0
        for rid, dur in durations.items():
            c = classes.get(rid)
            if c is None:
                continue
            acc += dur * (pop.get(c, 0) / total)
        return acc

    before_mean = class_mean(before_dur, before_class, before_pop, total_before)
    after_mean = class_mean(after_dur, after_class, before_pop, total_before)

    if before_mean == 0:
        ratio = None
    else:
        ratio = after_mean / before_mean

    if ratio is None:
        return {"findings": findings, "unresolved": unresolved, "ratio": None}

    if ratio > 1.2 + 1e-8:
        findings.append("latency_regression")
    elif ratio < 0.8 - 1e-8:
        findings.append("latency_improvement")
    else:
        findings.append("latency_stable")

    return {"findings": findings, "unresolved": unresolved, "ratio": ratio}
